      INTEGER FUNCTION INDEX3(I2,I3,I4)CC     FINDS INDEX IN THIRD-ORDER TRANSFER MATRIXC      INCLUDE 'INDX.CIN'      DIMENSION       ICNT(6), ITOT(3)      EQUIVALENCE     (ITOT(1),IA), (ITOT(2),IB), (ITOT(3),IC)C      DO 10 J = 1, 6      ICNT(J) = 0   10 CONTINUE      ICNT(I2) = ICNT(I2) + 1      ICNT(I3) = ICNT(I3) + 1      ICNT(I4) = ICNT(I4) + 1C      K = 1      DO 30 J = 1, 3   20   IF (ICNT(K) .EQ. 0) THEN        K = K + 1        GO TO 20      ENDIF      ITOT(J) = K      ICNT(K) = ICNT(K) - 1   30 CONTINUE      INDEX3 = INDX3(IC) + INDX2(IB) + IA      RETURN      END